mapper.select:
SELECT id, from_user_id AS fromUserId, to_user_id AS toUserId, type, version, update_time AS updateTime
FROM t_following
WHERE from_user_id=#{from} AND to_user_id=#{to}

SELECT id, from_user_id AS fromUserId, to_user_id AS toUserId, type, version, update_time AS updateTime
FROM t_follower
